        table.put("%1$s is too dark for Facebook's light mode text to stay readable. Pick a lighter color. Grays down to about %2$s work.",
                "%1$s \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0442\u0435\u043c\u043d\u044b\u0439, \u0438 \u0442\u0435\u043a\u0441\u0442 \u0441\u0432\u0435\u0442\u043b\u043e\u0433\u043e \u0440\u0435\u0436\u0438\u043c\u0430 Facebook \u0431\u0443\u0434\u0435\u0442 \u043f\u043b\u043e\u0445\u043e \u0447\u0438\u0442\u0430\u0442\u044c\u0441\u044f. \u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0431\u043e\u043b\u0435\u0435 \u0441\u0432\u0435\u0442\u043b\u044b\u0439 \u0446\u0432\u0435\u0442. \u041f\u043e\u0434\u043e\u0439\u0434\u0443\u0442 \u043e\u0442\u0442\u0435\u043d\u043a\u0438 \u0441\u0435\u0440\u043e\u0433\u043e \u0432\u043f\u043b\u043e\u0442\u044c \u0434\u043e %2$s.");
        table.put("%1$s is too light for Facebook's text to stay readable. Pick a darker color. Grays up to about %2$s work.",
                "%1$s \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0441\u0432\u0435\u0442\u043b\u044b\u0439, \u0438 \u0442\u0435\u043a\u0441\u0442 Facebook \u0431\u0443\u0434\u0435\u0442 \u043f\u043b\u043e\u0445\u043e \u0447\u0438\u0442\u0430\u0442\u044c\u0441\u044f. \u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0431\u043e\u043b\u0435\u0435 \u0442\u0435\u043c\u043d\u044b\u0439 \u0446\u0432\u0435\u0442. \u041f\u043e\u0434\u043e\u0439\u0434\u0443\u0442 \u043e\u0442\u0442\u0435\u043d\u043a\u0438 \u0441\u0435\u0440\u043e\u0433\u043e \u0434\u043e %2$s.");
        table.put("%1$s isn't a valid app ID, so the app stays as it was.",
                "%1$s \u043d\u0435 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b\u043c ID \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u043e.");
        table.put("%1$s of %2$s",
                "%1$s \u0438\u0437 %2$s");
