        table.put("Allow screenshots",
                "\u0420\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u044c \u0441\u043d\u0438\u043c\u043a\u0438 \u044d\u043a\u0440\u0430\u043d\u0430");
